class chain_sink {                                        // no logging dependency
  EVP_MAC_CTX *ctx_; std::array<unsigned char, 32> prev_{}; std::uint64_t seq_{0};
 public:
  void record(std::span<const std::byte> canon) {
    unsigned char tag[32], s[8]; std::size_t n = sizeof tag;
    for (int i = 0; i < 8; ++i) s[7 - i] = (seq_ >> (8 * i)) & 0xffu;    // big-endian seq
    EVP_MAC_init(ctx_, key_.data(), key_.size(), params_);      // params: digest = SHA256
    EVP_MAC_update(ctx_, prev_.data(), prev_.size()); EVP_MAC_update(ctx_, s, sizeof s);
    EVP_MAC_update(ctx_, reinterpret_cast<const unsigned char *>(canon.data()), canon.size());
    EVP_MAC_final(ctx_, tag, &n, sizeof tag);
    file_.append(seq_++, tag, canon); std::memcpy(prev_.data(), tag, n);   // O_APPEND + fsync
  }
};
